package cn.qinghe.mall.module.product.service.stock;
import cn.qinghe.mall.framework.tenant.config.TenantProperties;import cn.qinghe.mall.framework.tenant.core.context.TenantContextHolder;import cn.qinghe.mall.framework.tenant.core.db.*;
import cn.qinghe.mall.module.product.dal.mysql.stock.*;import cn.qinghe.mall.module.product.dal.mysql.catalog.ProductCatalogControlMapper;import cn.qinghe.mall.module.product.dal.dataobject.stock.*;
import com.baomidou.mybatisplus.core.MybatisConfiguration;import com.baomidou.mybatisplus.core.config.GlobalConfig;import com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor;import com.baomidou.mybatisplus.spring.MybatisSqlSessionFactoryBean;
import org.mybatis.spring.SqlSessionTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;
import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;
/** DEC-076 exact isolated DB; immutable synthetic markers only, workers roll back, no SKU write. */
@EnabledIfEnvironmentVariable(named="QINGHE_COMMERCE_TEST_ENABLED",matches="true")
class StockRegistrationConcurrencyTest {
 DriverManagerDataSource ds;JdbcTemplate jdbc;ProductOrderStockMapper orders;ProductStockMapper operations;ProductCatalogControlMapper catalog;
 @BeforeEach void setup()throws Exception{
  ds=new DriverManagerDataSource("jdbc:mysql://127.0.0.1:3306/qinghe_product_commerce_test?serverTimezone=Asia/Shanghai",System.getenv().getOrDefault("QINGHE_DB_USERNAME","root"),System.getenv("QINGHE_DB_PASSWORD"));try(java.sql.Connection c=ds.getConnection()){assertThat(c.getCatalog()).isEqualTo("qinghe_product_commerce_test");}
  MybatisConfiguration cfg=new MybatisConfiguration();cfg.setMapUnderscoreToCamelCase(true);MybatisPlusInterceptor plugin=new MybatisPlusInterceptor();plugin.addInnerInterceptor(new MySqlTenantLineInnerInterceptor(new TenantDatabaseInterceptor(new TenantProperties())));MybatisSqlSessionFactoryBean f=new MybatisSqlSessionFactoryBean();f.setDataSource(ds);f.setConfiguration(cfg);f.setPlugins(plugin);GlobalConfig g=new GlobalConfig();g.setBanner(false);g.setDbConfig(new GlobalConfig.DbConfig());f.setGlobalConfig(g);org.apache.ibatis.session.SqlSessionFactory sf=f.getObject();for(Class<?> c:new Class<?>[]{ProductOrderStockMapper.class,ProductStockMapper.class,ProductCatalogControlMapper.class})sf.getConfiguration().addMapper(c);SqlSessionTemplate s=new SqlSessionTemplate(sf);orders=s.getMapper(ProductOrderStockMapper.class);operations=s.getMapper(ProductStockMapper.class);catalog=s.getMapper(ProductCatalogControlMapper.class);jdbc=new JdbcTemplate(ds);
  jdbc.update("INSERT INTO product_order_stock(tenant_id,order_id,user_id,status,release_reason) VALUES(72000001,8990000011,72000001001,0,'CREATE_FAILED') ON DUPLICATE KEY UPDATE order_id=order_id");
  jdbc.update("INSERT INTO product_stock_operation(tenant_id,operation_key,kind,spu_id,request_hash,actor_user_id,reason) VALUES(72000001,'manual:commerce-concurrency','ADJUST',72000001101,?,101,'Synthetic concurrency fixture') ON DUPLICATE KEY UPDATE operation_key=operation_key",hash());
  jdbc.update("INSERT INTO product_catalog_mutex(tenant_id) VALUES(72000001) ON DUPLICATE KEY UPDATE tenant_id=tenant_id");
 }
 @Test void repeatedOrderDeductionRegistrationDoesNotDeadlock()throws Exception{race(()->{assertThat(orders.ensure(order(8990000011L))).isZero();pause();ProductOrderStockDO o=orders.lock(72000001L,8990000011L);assertThat(o.getStatus()).isZero();assertThat(o.getRequestHash()).isNull();assertThat(o.getReleaseReason()).isEqualTo("CREATE_FAILED");});}
 @Test void repeatedManualOperationRegistrationDoesNotDeadlock()throws Exception{race(()->{assertThat(operations.ensureOperation(operation("manual:commerce-concurrency"))).isZero();pause();assertThat(operations.lockOperation(72000001L,"manual:commerce-concurrency").getReason()).isEqualTo("Synthetic concurrency fixture");});}
 @Test void repeatedCatalogMutexRegistrationDoesNotDeadlock()throws Exception{race(()->{catalog.ensureTenant(72000001L);pause();assertThat(catalog.lockTenant(72000001L)).isEqualTo(72000001L);});}
 @Test void generatedKeysDistinguishFreshAndDuplicateEvenWithFoundRows(){TenantContextHolder.setTenantId(72000001L);try{new TransactionTemplate(new DataSourceTransactionManager(ds)).executeWithoutResult(tx->{tx.setRollbackOnly();ProductOrderStockDO a=order(8990000012L);assertThat(orders.ensure(a)).isEqualTo(1);assertThat(a.getId()).isPositive();ProductOrderStockDO b=order(8990000012L);b.setId(a.getId());assertThat(orders.ensure(b)).isZero();assertThat(b.getId()).isNull();ProductStockOperationDO x=operation("manual:commerce-fresh");assertThat(operations.ensureOperation(x)).isEqualTo(1);assertThat(x.getId()).isPositive();ProductStockOperationDO y=operation("manual:commerce-fresh");y.setId(x.getId());assertThat(operations.ensureOperation(y)).isZero();assertThat(y.getId()).isNull();});}finally{TenantContextHolder.clear();}}
 @Test void generatedKeyFreshnessAlsoWorksWithAffectedRows(){ds.setUrl(ds.getUrl()+"&useAffectedRows=true");generatedKeysDistinguishFreshAndDuplicateEvenWithFoundRows();}
 private ProductOrderStockDO order(Long id){ProductOrderStockDO r=new ProductOrderStockDO();r.setTenantId(72000001L);r.setOrderId(id);r.setUserId(72000001001L);r.setStatus(1);r.setRequestHash(hash());r.setRequestSnapshot("{}");return r;}
 private ProductStockOperationDO operation(String key){ProductStockOperationDO r=new ProductStockOperationDO();r.setTenantId(72000001L);r.setOperationKey(key);r.setKind("ADJUST");r.setSpuId(72000001101L);r.setActorUserId(101L);r.setRequestHash(hash());r.setReason("Synthetic concurrency fixture");return r;}
 private String hash(){return new String(new char[64]).replace('\0','a');}
 private void pause(){try{Thread.sleep(200);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}
 private void race(Runnable work)throws Exception{Long before=jdbc.queryForObject("SELECT SUM(stock) FROM product_sku",Long.class);CyclicBarrier start=new CyclicBarrier(2);ExecutorService pool=Executors.newFixedThreadPool(2);Callable<Void> task=()->{TenantContextHolder.setTenantId(72000001L);try{new TransactionTemplate(new DataSourceTransactionManager(ds)).executeWithoutResult(tx->{tx.setRollbackOnly();try{start.await(3,TimeUnit.SECONDS);}catch(Exception e){throw new IllegalStateException(e);}work.run();});return null;}finally{TenantContextHolder.clear();}};try{Future<Void>a=pool.submit(task),b=pool.submit(task);a.get(10,TimeUnit.SECONDS);b.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT SUM(stock) FROM product_sku",Long.class)).isEqualTo(before);}
}
